// U2FAuthenticateChallenge contains a challenge for each of a user's U2F
// devices. The embedded challenge preserves the original single-device JSON
// response for clients that do not understand the challenges field.
type U2FAuthenticateChallenge struct {
	*u2f.AuthenticateChallenge
	Challenges []u2f.AuthenticateChallenge `json:"challenges"`
}

// GetChallenges returns all available challenges, including a single challenge
// received from an older auth server.
func (c *U2FAuthenticateChallenge) GetChallenges() []u2f.AuthenticateChallenge {
	if c == nil {
		return nil
	}
	if len(c.Challenges) > 0 {
		return c.Challenges
	}
	if c.AuthenticateChallenge != nil {
		return []u2f.AuthenticateChallenge{*c.AuthenticateChallenge}
	}
	return nil
}

func (a *Server) U2FSignRequest(user string, password []byte) (*U2FAuthenticateChallenge, error) {
	ctx := context.TODO()
	cap, err := a.GetAuthPreference()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	u2fConfig, err := cap.GetU2F()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = a.WithUserLock(user, func() error {
		return a.CheckPasswordWOToken(user, password)
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	devs, err := a.GetMFADevices(ctx, user)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	response := new(U2FAuthenticateChallenge)
	for _, dev := range devs {
		if dev.GetU2F() == nil {
			continue
		}
		challenge, err := u2f.AuthenticateInit(ctx, u2f.AuthenticateInitParams{
			Dev:        dev,
			AppConfig:  *u2fConfig,
			StorageKey: user,
			Storage:    a.Identity,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if response.AuthenticateChallenge == nil {
			response.AuthenticateChallenge = challenge
		}
		response.Challenges = append(response.Challenges, *challenge)
	}
	if len(response.Challenges) == 0 {
		return nil, trace.NotFound("no U2F devices found for user %q", user)
	}
	return response, nil
}

func (a *Server) CheckU2FSignResponse(ctx context.Context, user string, response *u2f.AuthenticateChallengeResponse) error {
	// before trying to register a user, see U2F is actually setup on the backend
	cap, err := a.GetAuthPreference()
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = cap.GetU2F()
	c.Assert(json.Unmarshal(re.Bytes(), &u2fSignReq), IsNil)

	u2fSignResp, err = s.mockU2F.SignResponse(&u2fSignReq)
	c.Assert(err, IsNil)

	_, err = clt.PostJSON(context.Background(), clt.Endpoint("webapi", "u2f", "sessions"), u2fSignResponseReq{
		User:            "bob",
		U2FSignResponse: *u2fSignResp,
	})
	c.Assert(err, NotNil)
}

func (s *WebSuite) TestU2FLoginWithMultipleDevices(c *C) {
	cap, err := services.NewAuthPreference(services.AuthPreferenceSpecV2{
		Type:         teleport.Local,
		SecondFactor: teleport.U2F,
		U2F: &services.U2F{
			AppID:  "https://" + s.server.ClusterName(),
			Facets: []string{"https://" + s.server.ClusterName()},
		},
	})
	c.Assert(err, IsNil)
	c.Assert(s.server.Auth().SetAuthPreference(cap), IsNil)

	s.createUser(c, "bob", "root", "password", "")
	token, err := s.server.Auth().CreateResetPasswordToken(context.TODO(), auth.CreateResetPasswordTokenRequest{
		Name: "bob",
	})
	c.Assert(err, IsNil)
	regReq, err := s.proxyClient.GetSignupU2FRegisterRequest(token.GetName())
	c.Assert(err, IsNil)
	regResp, err := s.mockU2F.RegisterResponse(regReq)
	c.Assert(err, IsNil)
	password := []byte("abc123")
	_, err = s.proxyClient.ChangePasswordWithToken(context.TODO(), auth.ChangePasswordWithTokenRequest{
		TokenID:             token.GetName(),
		U2FRegisterResponse: *regResp,
		Password:            password,
	})
	c.Assert(err, IsNil)

	secondKey, err := mocku2f.Create()
	c.Assert(err, IsNil)
	secondDevice, err := u2f.NewDevice("backup", &u2f.Registration{
		KeyHandle: secondKey.KeyHandle,
		PubKey:    secondKey.PrivateKey.PublicKey,
	}, s.clock.Now())
	c.Assert(err, IsNil)
	c.Assert(s.server.Auth().UpsertMFADevice(context.Background(), "bob", secondDevice), IsNil)

	clt := s.client()
	re, err := clt.PostJSON(context.Background(), clt.Endpoint("webapi", "u2f", "signrequest"), client.U2fSignRequestReq{
		User: "bob",
		Pass: string(password),
	})
	c.Assert(err, IsNil)
	var signReq auth.U2FAuthenticateChallenge
	c.Assert(json.Unmarshal(re.Bytes(), &signReq), IsNil)
	c.Assert(len(signReq.Challenges), Equals, 2)

	// Older web clients can continue to decode the flat challenge fields.
	var legacyReq u2f.AuthenticateChallenge
	c.Assert(json.Unmarshal(re.Bytes(), &legacyReq), IsNil)
	legacyInList := false
	for _, challenge := range signReq.Challenges {
		if challenge == legacyReq {
			legacyInList = true
		}
	}
	c.Assert(legacyInList, Equals, true)

	// Authenticate using the key that does not own the flat legacy challenge.
	var signResp *u2f.AuthenticateChallengeResponse
	for _, challenge := range signReq.Challenges {
		if challenge.KeyHandle == legacyReq.KeyHandle {
			continue
		}
		for _, key := range []*mocku2f.Key{s.mockU2F, secondKey} {
			signResp, err = key.SignResponse(&challenge)
			if err == nil {
				break
			}
		}
	}
	c.Assert(signResp, NotNil)
	_, err = clt.PostJSON(context.Background(), clt.Endpoint("webapi", "u2f", "sessions"), u2fSignResponseReq{
		User:            "bob",
		U2FSignResponse: *signResp,
	})
	c.Assert(err, IsNil)
}

